<?php ($editing=isset($resource)); ?><form method="POST" action="<?php echo e($editing?route('admin.resources.update',$resource):route('admin.resources.store')); ?>" class="rounded-lg border border-[#EBEFEA] bg-white p-[18px] grid gap-3 [&_label]:grid [&_label]:gap-1.5 [&_input]:rounded-md [&_input]:border [&_input]:border-[#DDE2DF] [&_input]:bg-white [&_input]:px-2.5 [&_input]:py-2 [&_input]:text-sm [&_textarea]:min-h-[100px] [&_textarea]:rounded-md [&_textarea]:border [&_textarea]:border-[#DDE2DF] [&_textarea]:bg-white [&_textarea]:px-2.5 [&_textarea]:py-2 [&_textarea]:text-sm [&_select]:rounded-md [&_select]:border [&_select]:border-[#DDE2DF] [&_select]:bg-white [&_select]:px-2.5 [&_select]:py-2 [&_select]:text-sm"><?php echo csrf_field(); ?> <?php if($editing): ?><?php echo method_field('PUT'); ?><?php endif; ?><label>Type<select name="type"><?php $__currentLoopData = ['book','research_paper','equipment','course','website','tool','other']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $v): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($v); ?>" <?php if(old('type',$editing?$resource->type:'other')===$v): echo 'selected'; endif; ?>><?php echo e(ucwords(str_replace('_',' ',$v))); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label>Title<input name="title" required value="<?php echo e(old('title',$editing?$resource->title:'')); ?>"></label><label>Description<textarea name="description"><?php echo e(old('description',$editing?$resource->description:'')); ?></textarea></label><label>External URL<input type="url" name="url" value="<?php echo e(old('url',$editing?$resource->url:'')); ?>"></label><label>Sort Order<input type="number" name="sort_order" min="0" value="<?php echo e(old('sort_order',$editing?$resource->sort_order:0)); ?>"></label><label class="flex items-center gap-2 text-sm"><input type="checkbox" name="is_featured" value="1" <?php if(old('is_featured',$editing?$resource->is_featured:false)): echo 'checked'; endif; ?>> Featured</label><label class="flex items-center gap-2 text-sm"><input type="checkbox" name="is_active" value="1" <?php if(old('is_active',$editing?$resource->is_active:true)): echo 'checked'; endif; ?>> Visible</label><button class="inline-flex h-11 cursor-pointer items-center justify-center gap-2 rounded-md border border-transparent px-3.5 text-sm font-medium no-underline transition bg-[#526A5A] text-white hover:bg-[#293C32]"><?php echo e($editing?'Save Resource':'Create Resource'); ?></button></form><?php /**PATH /Users/ferdy/project-fl/vet-cms/backend/resources/views/admin/resources/_form.blade.php ENDPATH**/ ?>